import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs['DIM_ACCOUNT'].copy()
    stg = inputs['STG_ACCOUNT'].copy()

    # --- type coercion -----------------------------------------------
    if len(dim):
        dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
        dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    else:
        dim['eff_start_date'] = pd.to_datetime(dim.get('eff_start_date', pd.Series([], dtype='datetime64[ns]')))
        dim['eff_end_date'] = pd.to_datetime(dim.get('eff_end_date', pd.Series([], dtype='datetime64[ns]')))

    if len(stg):
        stg['update_date'] = pd.to_datetime(stg['update_date'])
    else:
        stg['update_date'] = pd.to_datetime(stg.get('update_date', pd.Series([], dtype='datetime64[ns]')))

    # --- build initial per-account version lists ----------------------
    versions = {}
    for acc_id, grp in dim.groupby('account_id'):
        lst = []
        for _, row in grp.iterrows():
            lst.append({
                'plan': row['plan'],
                'eff_start_date': row['eff_start_date'],
                'eff_end_date': row['eff_end_date'],
                'is_current': row['is_current'],
            })
        versions[acc_id] = lst

    def plan_eq(a, b):
        a_null = pd.isna(a)
        b_null = pd.isna(b)
        if a_null and b_null:
            return True
        if a_null or b_null:
            return False
        return a == b

    # --- process staged records in cursor order ------------------------
    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='stable')

    for _, s in stg_sorted.iterrows():
        acc_id = s['account_id']
        plan = s['plan']
        upd = s['update_date']

        if acc_id not in versions or len(versions[acc_id]) == 0:
            versions.setdefault(acc_id, []).append({
                'plan': plan,
                'eff_start_date': upd,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
            continue

        vlist = versions[acc_id]

        # find the version covering upd (start <= upd < end), end NULL = open/infinite
        covering = None
        for v in vlist:
            start = v['eff_start_date']
            end = v['eff_end_date']
            if start <= upd and (pd.isna(end) or upd < end):
                covering = v
                break

        if covering is None:
            # earlier than the account's first version
            f = min(vlist, key=lambda v: v['eff_start_date'])
            vlist.append({
                'plan': plan,
                'eff_start_date': upd,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
        else:
            v = covering
            if plan_eq(v['plan'], plan):
                # unchanged -> no-op, no new version
                pass
            elif upd == v['eff_start_date']:
                # same-day correction
                v['plan'] = plan
            else:
                # split v at upd
                vlist.append({
                    'plan': plan,
                    'eff_start_date': upd,
                    'eff_end_date': v['eff_end_date'],
                    'is_current': v['is_current'],
                })
                v['eff_end_date'] = upd
                v['is_current'] = 0

    # --- build output ----------------------------------------------------
    rows = []
    for acc_id, vlist in versions.items():
        for v in vlist:
            rows.append({
                'account_id': acc_id,
                'plan': v['plan'],
                'eff_start_date': v['eff_start_date'],
                'eff_end_date': v['eff_end_date'],
                'is_current': v['is_current'],
            })

    out = pd.DataFrame(
        rows,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current']
    )

    if len(out):
        out = out.sort_values(['account_id', 'eff_start_date'], kind='stable').reset_index(drop=True)

    return {'dim_account_out': out}
